package com.inhuman.ui.chat

/**
 * The one place the "what might you say next" block is defined.
 *
 * ## Why a text block instead of a second model call
 *
 * The product rule is that advice costs no extra request: it is a few more lines
 * in the same answer. A tool call would need a definition, a result, and a
 * place in the transcript; a second completion would bill the user for a
 * question they did not ask. The block is the smallest thing that can be
 * parsed deterministically and still generated by the model.
 *
 * ## Why it is hidden while streaming
 *
 * The model emits the block at the end, so a reader would otherwise watch the
 * marker and the raw suggestion list arrive as part of the prose. [visible]
 * returns the answer before the marker and holds back a trailing *prefix* of
 * it, so a split marker never flickers on screen. It is monotonic: once text is
 * visible it stays visible, which is what the incremental Markdown cursor
 * requires.
 *
 * ## Why the block is not stored
 *
 * The transcript stores the answer without it. Suggestions are a live offer to
 * fill the composer, not a fact about what was said; a reopened conversation
 * has no composer context worth restoring them for. Persisting them would also
 * put them back on the wire on every later turn.
 */
internal const val ADVICE_OPEN = "<<<suggestions"

internal const val ADVICE_CLOSE = ">>>"

/**
 * Appended only to a request, never stored.
 *
 * It is English because it is prompt text, like the no-tool retry instruction.
 * The examples are deliberately ordinary: a model that copies them produces
 * useful suggestions, and one that writes its own produces better ones.
 */
internal const val ADVICE_INSTRUCTION =
	"After the final answer, append a block on its own lines, exactly in this shape:\n" +
		"$ADVICE_OPEN\n" +
		"Continue\n" +
		"Explain the second point\n" +
		"$ADVICE_CLOSE\n" +
		"Replace the two example lines with 2-3 short follow-ups the user might send next, " +
		"one per line, at most 60 characters each. Do not use bullets or numbering. " +
		"Do not include the block when you are calling a tool, and never mention it in the answer."

/** The answer with the block removed, and the suggestions it held. */
internal data class AdviceResult(
	val visibleText: String,
	val suggestions: List<String>,
)

internal object Advice {

	/** The answer as it should be shown while tokens are still arriving. */
	fun visible(text: String): String {
		val open = text.indexOf(ADVICE_OPEN)
		if (open >= 0) return text.substring(0, open)
		// Hold back a suffix that could still become the marker. Without this,
		// `<<<sug` would render for one frame and then vanish.
		for (length in minOf(ADVICE_OPEN.length - 1, text.length) downTo 1) {
			if (text.regionMatches(text.length - length, ADVICE_OPEN, 0, length)) {
				return text.substring(0, text.length - length)
			}
		}
		return text
	}

	/**
	 * Split a completed answer into visible text and suggestions.
	 *
	 * A block with no closing marker (the answer was cut off) leaves the visible
	 * text before the marker and produces no suggestions. Text after a closed
	 * block is kept after the answer rather than dropped: the instruction says
	 * "at the end", but a model that adds a sign-off should not lose it.
	 */
	fun parse(text: String): AdviceResult {
		val open = text.indexOf(ADVICE_OPEN)
		if (open < 0) return AdviceResult(text.trimEnd(), emptyList())
		val visible = text.substring(0, open).trimEnd()
		val rest = text.substring(open + ADVICE_OPEN.length)
		val close = rest.indexOf(ADVICE_CLOSE)
		if (close < 0) return AdviceResult(visible, emptyList())
		val suggestions = rest.substring(0, close)
			.lineSequence()
			.map { line ->
				line.trim()
					.replace(Regex("^\\d+[.)]\\s*"), "")
					.trimStart('-', '*')
					.trim()
			}
			.filter { it.isNotEmpty() }
			.map { it.take(80) }
			.distinct()
			.take(3)
			.toList()
		val after = rest.substring(close + ADVICE_CLOSE.length).trim()
		val clean = if (after.isEmpty()) visible else "${visible}\n\n$after".trim()
		return AdviceResult(clean, suggestions)
	}
}